<template>
  <!-- #ifdef H5 -->
  <SravxOfficialH5 />
  <!-- #endif -->
  <!-- #ifndef H5 -->
  <view class="container">
    <view class="search-bar" :style="{paddingTop:`${navBarTop}rpx`,paddingRight:`${capsuleRight}rpx`}">
      <view class="brand-lockup" :style="{height:`${navBarHeight}rpx`}" @click="goSearch"><image class="brand-mark" src="/static/navigation/sravx-mark.png" mode="aspectFit"/><text class="brand-name">SRAVX</text></view>
      <view class="search-inner" :style="{height:`${navBarHeight}rpx`}" @click="goSearch"><view class="search-icon"><view class="search-circle"/><view class="search-handle"/></view><text class="search-placeholder">搜索产品与服务</text></view>
    </view>
    <scroll-view scroll-y class="main-scroll" :style="{paddingTop:`${scrollPaddingTop}rpx`}" refresher-enabled :refresher-triggered="refreshing" @refresherrefresh="refresh">
      <view class="intro-block"><text class="page-title">产品</text></view>
      <scroll-view class="series-scroll" scroll-x>
        <view class="series-row">
          <view v-for="item in homeSeries" :key="item.key" class="series-card" @click="goSeries(item.key)">
            <view class="series-image-wrap"><image class="series-image" :src="item.image" mode="aspectFit" /></view>
            <view class="series-copy">
              <text class="series-material">{{ item.material }}</text>
