      <view class="swiper-wrap"><swiper class="banner-swiper" autoplay circular :interval="4000" :duration="500" @change="swiperCurrent=$event.detail.current"><swiper-item v-for="item in banners" :key="item.id"><view class="banner-item" @click="goShop"><view class="banner-media"><image class="banner-img" :src="item.image||'/static/navigation/sravx-mark.png'" mode="aspectFill"/></view><view class="banner-detail"><text class="banner-eyebrow">SRAVX PROFESSIONAL TOOLS</text><text class="banner-title">{{item.title}}</text><text class="banner-subtitle">{{item.subtitle||'为精准、稳定的专业工作而设计'}}</text></view><view class="banner-footer"><text class="banner-price">专业美容工具系列</text><view class="banner-action">查看系列</view></view></view></swiper-item></swiper><view class="swiper-dots"><view v-for="(item,index) in banners" :key="item.id" class="dot" :class="{'dot-active':swiperCurrent===index}"/></view></view>
