      <scroll-view v-else class="product-scroll" scroll-x><view class="product-track"><view v-for="(item,index) in products" :key="item.id" class="product-card" @click="goProduct(item.id)"><view class="product-img-wrap"><image class="product-img" :src="item.image||item.cover_image||'/static/navigation/sravx-mark.png'" mode="aspectFill"/><view class="product-index">{{index+1}}</view></view><view class="product-info"><text class="product-name">{{item.short_name||item.name}}</text><text class="product-desc">{{item.desc||item.description}}</text></view><view class="product-footer"><text class="product-price">¥{{item.price}} 起</text><view class="product-action">查看</view></view></view></view></scroll-view>
