<script>
import api from '../../common/api.js'
import SravxTabBar from '../../components/SravxTabBar.vue'
import SravxOfficialH5 from '../../components/SravxOfficialH5.vue'
const SERIES=[{key:'basic',name:'Basic',material:'9Cr',caption:'入门专业款'},{key:'pro',name:'Pro',material:'440C',caption:'专业主力款'},{key:'master',name:'Master',material:'VG10',caption:'高阶专业款'},{key:'accessories',name:'配件',material:'收纳与养护',caption:'专业工作配套'}]
const FEATURES=[{key:'custom',kicker:'激光雕刻',title:'定制服务',description:'通过精密激光热加工，在剪刀上留下文字或图案，制作独属于你的工具。'},{key:'protect',kicker:'工具服务计划',title:'SRAVX Protect',description:'延长保修期，获得专属换购权益。'},{key:'apprentice',kicker:'宠物美容学徒认证',title:'学徒支持',description:'通过学徒认证，获得专属工具支持与购置权益。'},{key:'tradein',kicker:'换购服务',title:'SRAVX 换购优惠',description:'旧工具换购权益，以后续官方活动规则为准。'}]
function list(value){return api.asList(value)} function normalize(item={}){const image=api.productImage(item)||'/static/navigation/sravx-mark.png';return{...item,image,cover_image:image,short_name:item.short_name||item.name||'未命名商品',desc:item.desc||item.description||''}}
export default {components:{SravxTabBar,SravxOfficialH5},data(){return{banners:[],products:[],homeSeries:[],serviceFeatures:FEATURES,featureCurrent:0,swiperCurrent:0,navBarTop:0,navBarHeight:64,capsuleRight:200,scrollPaddingTop:88,loading:true,refreshing:false}},onLoad(){// #ifndef H5
this.initNav();this.load()
// #endif
},onShareAppMessage(){return{title:'Sravx',path:'/pages/index/index'}},onShareTimeline(){return{title:'Sravx'}},methods:{initNav(){try{const menu=uni.getMenuButtonBoundingClientRect(),sys=uni.getSystemInfoSync(),ratio=750/sys.screenWidth;this.navBarTop=Math.ceil(menu.top*ratio);this.navBarHeight=Math.ceil(menu.height*ratio);this.capsuleRight=Math.ceil((sys.screenWidth-menu.left+8)*ratio);this.scrollPaddingTop=Math.ceil((menu.bottom+12)*ratio)}catch(error){}},async load(){this.loading=true;try{const result=await api.getHomeProducts();const products=list(result.products&&result.products.length?result.products:result).map(normalize);const banners=list(result.banners);this.products=products;this.banners=banners.length?banners:[{id:'fallback',image:'/static/navigation/sravx-mark.png',title:'Sravx'}];this.homeSeries=SERIES.map(series=>{const found=products.find(product=>{const text=`${product.name||''} ${product.desc||''} ${product.series||''} ${product.series_name||''} ${product.category_name||''}`.toLowerCase();return series.key==='accessories'?/(配件|套装|收纳|养护|保养|服务)/.test(text):text.includes(series.key)});return{...series,image:(found&&found.image)||'/static/navigation/sravx-mark.png'}})}catch(error){uni.showToast({title:error.message||'加载失败',icon:'none'})}finally{this.loading=false;this.refreshing=false}},refresh(){this.refreshing=true;this.load()},goSearch(){uni.navigateTo({url:'/pages/search/index'})},goShop(){uni.navigateTo({url:'/pages/shop/index'})},goSeries(series){uni.navigateTo({url:`/pages/shop/index?series=${series}`})},goProduct(id){uni.navigateTo({url:`/pages/product-detail/index?id=${id}`})}}}
</script>
